public boolean validateWrite()
{
    boolean ret;
    ret = next validateWrite();
    if(this.METVendLegalEntityID && this.InvoiceVendorAccountNumber && (this.VendorAccountNumber != this.InvoiceVendorAccountNumber ))
    {
        ret=false;
        error("@MET:VendorLegalEntityIdValidation");
    }
    return ret;
}
